*** Add File: src/cli.ts
+import { readFile, rename, unlink } from "node:fs/promises";
+import { dirname, basename, join } from "node:path";
+
+type Status = "open" | "done";
+
+type Task = {
+  id: number;
+  title: string;
+  status: Status;
+  tags: string[];
+  due?: string;
+  createdAt: string;
+  completedAt?: string;
+};
+
+type Database = {
+  version: 1;
+  nextId: number;
+  tasks: Task[];
+};
+
+const file = process.env.TASKBOARD_FILE || join(process.cwd(), ".taskboard.json");
+
+function fail(message: string): never {
+  throw new Error(message);
+}
+
+function isDate(value: string): boolean {
+  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
+  if (!match) return false;
+  const year = Number(match[1]);
+  const month = Number(match[2]);
+  const day = Number(match[3]);
+  const date = new Date(Date.UTC(year, month - 1, day));
+  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
+}
+
+function normalizeTag(value: string): string {
+  return value.trim().toLowerCase();
+}
+
+function validTask(value: unknown): value is Task {
+  if (!value || typeof value !== "object") return false;
+  const task = value as Record<string, unknown>;
+  const keys = Object.keys(task);
+  if (keys.some((key) => !["id", "title", "status", "tags", "due", "createdAt", "completedAt"].includes(key))) return false;
+  if (!Number.isSafeInteger(task.id) || (task.id as number) < 1) return false;
+  if (typeof task.title !== "string" || task.title.trim() === "") return false;
+  if (task.status !== "open" && task.status !== "done") return false;
+  if (!Array.isArray(task.tags) || task.tags.some((tag) => typeof tag !== "string" || tag === "" || tag !== normalizeTag(tag))) return false;
+  if (new Set(task.tags).size !== task.tags.length) return false;
+  if (task.due !== undefined && (typeof task.due !== "string" || !isDate(task.due))) return false;
+  if (typeof task.createdAt !== "string" || Number.isNaN(Date.parse(task.createdAt))) return false;
+  if (task.status === "done") {
+    if (typeof task.completedAt !== "string" || Number.isNaN(Date.parse(task.completedAt))) return false;
+  } else if (task.completedAt !== undefined) return false;
+  return true;
+}
+
+async function loadDatabase(): Promise<Database> {
+  let text: string;
+  try {
+    text = await readFile(file, "utf8");
+  } catch (error) {
+    if ((error as NodeJS.ErrnoException).code === "ENOENT") return { version: 1, nextId: 1, tasks: [] };
+    throw error;
+  }
+
+  let value: unknown;
+  try {
+    value = JSON.parse(text);
+  } catch {
+    fail("Malformed taskboard database: invalid JSON");
+  }
+  if (!value || typeof value !== "object") fail("Malformed taskboard database: invalid structure");
+  const db = value as Record<string, unknown>;
+  if (Object.keys(db).some((key) => !["version", "nextId", "tasks"].includes(key)) || db.version !== 1 || !Number.isSafeInteger(db.nextId) || (db.nextId as number) < 1 || !Array.isArray(db.tasks) || !db.tasks.every(validTask)) {
+    fail("Malformed taskboard database: invalid structure");
+  }
+  const ids = db.tasks.map((task) => task.id);
+  if (new Set(ids).size !== ids.length || ids.some((id) => id >= (db.nextId as number))) fail("Malformed taskboard database: invalid task IDs");
+  return value as Database;
+}
+
+async function saveDatabase(db: Database): Promise<void> {
+  const temporary = join(dirname(file), `.${basename(file)}.${process.pid}.${crypto.randomUUID()}.tmp`);
+  try {
+    await Bun.write(temporary, `${JSON.stringify(db, null, 2)}\n`);
+    await rename(temporary, file);
+  } catch (error) {
+    await unlink(temporary).catch(() => {});
+    throw error;
+  }
+}
+
+function parseOptions(args: string[], allowed: Set<string>): Record<string, string> {
+  const options: Record<string, string> = {};
+  for (let index = 0; index < args.length; index += 2) {
+    const flag = args[index];
+    if (!flag?.startsWith("--") || !allowed.has(flag)) fail(`Unknown flag: ${flag ?? ""}`);
+    if (Object.hasOwn(options, flag)) fail(`Duplicate flag: ${flag}`);
+    const value = args[index + 1];
+    if (value === undefined || value.startsWith("--")) fail(`Missing value for ${flag}`);
+    options[flag] = value;
+  }
+  return options;
+}
+
+function parseId(args: string[]): number {
+  if (args.length !== 1 || !/^[1-9]\d*$/.test(args[0])) fail("Expected one positive integer task ID");
+  const id = Number(args[0]);
+  if (!Number.isSafeInteger(id)) fail("Task ID is too large");
+  return id;
+}
+
+function localToday(): string {
+  const now = new Date();
+  const year = now.getFullYear();
+  const month = String(now.getMonth() + 1).padStart(2, "0");
+  const day = String(now.getDate()).padStart(2, "0");
+  return `${year}-${month}-${day}`;
+}
+
+async function run(args: string[]): Promise<unknown> {
+  const [command, ...rest] = args;
+  if (!command) fail("Missing command");
+
+  if (command === "add") {
+    const options = parseOptions(rest, new Set(["--title", "--tags", "--due"]));
+    if (!("--title" in options)) fail("Missing required flag: --title");
+    const title = options["--title"].trim();
+    if (!title) fail("Title must not be empty");
+    const due = options["--due"];
+    if (due !== undefined && !isDate(due)) fail("Due date must be a valid YYYY-MM-DD date");
+    const tags = options["--tags"] === undefined
+      ? []
+      : [...new Set(options["--tags"].split(",").map(normalizeTag).filter(Boolean))];
+    const db = await loadDatabase();
+    const task: Task = { id: db.nextId++, title, status: "open", tags, createdAt: new Date().toISOString() };
+    if (due !== undefined) task.due = due;
+    db.tasks.push(task);
+    await saveDatabase(db);
+    return task;
+  }
+
+  if (command === "list") {
+    const options = parseOptions(rest, new Set(["--status", "--tag", "--overdue"]));
+    const status = options["--status"];
+    if (status !== undefined && status !== "open" && status !== "done") fail("Status must be open or done");
+    const tag = options["--tag"] === undefined ? undefined : normalizeTag(options["--tag"]);
+    if (tag === "") fail("Tag must not be empty");
+    const overdue = options["--overdue"];
+    if (overdue !== undefined && !isDate(overdue)) fail("Overdue date must be a valid YYYY-MM-DD date");
+    const db = await loadDatabase();
+    return db.tasks
+      .filter((task) => status === undefined || task.status === status)
+      .filter((task) => tag === undefined || task.tags.includes(tag))
+      .filter((task) => overdue === undefined || (task.status === "open" && task.due !== undefined && task.due < overdue))
+      .sort((a, b) => a.id - b.id);
+  }
+
+  if (command === "done") {
+    const id = parseId(rest);
+    const db = await loadDatabase();
+    const task = db.tasks.find((candidate) => candidate.id === id);
+    if (!task) fail(`Task ${id} not found`);
+    if (task.status === "open") {
+      task.status = "done";
+      task.completedAt = new Date().toISOString();
+      await saveDatabase(db);
+    }
+    return task;
+  }
+
+  if (command === "delete") {
+    const id = parseId(rest);
+    const db = await loadDatabase();
+    const index = db.tasks.findIndex((task) => task.id === id);
+    if (index === -1) fail(`Task ${id} not found`);
+    const [task] = db.tasks.splice(index, 1);
+    await saveDatabase(db);
+    return task;
+  }
+
+  if (command === "stats") {
+    if (rest.length) fail(`Unknown flag or argument: ${rest[0]}`);
+    const tasks = (await loadDatabase()).tasks;
+    const today = localToday();
+    return {
+      total: tasks.length,
+      open: tasks.filter((task) => task.status === "open").length,
+      done: tasks.filter((task) => task.status === "done").length,
+      overdue: tasks.filter((task) => task.status === "open" && task.due !== undefined && task.due < today).length,
+    };
+  }
+
+  fail(`Unknown command: ${command}`);
+}
+
+try {
+  console.log(JSON.stringify(await run(Bun.argv.slice(2))));
+} catch (error) {
+  const message = error instanceof Error ? error.message : String(error);
+  console.log(JSON.stringify({ error: message }));
+  console.error(`taskboard: ${message}`);
+  process.exitCode = 1;
+}
*** Add File: README.md
+# Taskboard CLI
+
+A dependency-free TypeScript task manager for Bun. Tasks are stored in `.taskboard.json` in the current directory, or in the path set by `TASKBOARD_FILE`.
+
+```sh
+bun run src/cli.ts add --title "Ship release" --tags work,urgent --due 2026-09-10
+bun run src/cli.ts list --status open --tag work
+bun run src/cli.ts list --overdue 2026-09-11
+bun run src/cli.ts done 1
+bun run src/cli.ts delete 1
+bun run src/cli.ts stats
+```
+
+Every invocation writes one JSON value to stdout. Errors also write a diagnostic to stderr and exit with a non-zero status. Database updates use a sibling temporary file followed by an atomic rename.
*** End Patch

